/**
 * dsh-notifier api 域 —— 草稿测试（dry-run）的编排：解析 draft → 内存归一化 → 直构单目标 → 实测。
 *
 * 禁写面（提案 B3，判据逐项钉）：本模块可触达的只有「纯函数 + 单目标出站」，结构上拿不到
 * appendHistory / recordStatus / revision 落盘 / FrameBus emit——ProbeEndpoints 的构造入参里
 * 根本没有 stores 与 frames；logger 入参存在但 dry-run 全程不调用（含路由收口的 500 兜底，
 * 见 probe/index.ts 的 testDraft）。browser 的 emitFrame 由目标直构时接空函数，零真通知。
 *
 * bypass（提案 B6）：直构目标跳过 enabled 门（新频道默认 false，否则恒 suppressed）；
 * 不走 judge / kindRoutes；bypass 节奏与重试（单次尝试）；禁 settle / archive / emitFrame；
 * 能力探测复用共享缓存只读（channels 侧）；读面只用 config.readConfig（含明文凭据，不外发）。
 */
import { channelIdOf } from "../../../../../shared/interface.ts";
import type { ChannelPort, ConfigPort, PipelinePort } from "../../../deps.ts";
import type { EffectiveConfig } from "../../../../pipeline/deps.ts";
import type { ProducedReason } from "../../../../shared/interface.ts";
import {
  DRY_RUN_BUDGET_MS,
  DRY_RUN_MAX_INFLIGHT,
  DryRunInputError,
  DryRunTimeoutError,
  TEST_NOTIFICATION,
} from "./type.ts";
import type { DryRunReason, DryRunResult } from "./type.ts";

/** dry-run 的域能力：只有组合根够得着的三个端口（与 ProbeEndpoints 的入参同源）。 */
export interface DryRunDeps {
  readonly config: ConfigPort;
  readonly pipeline: PipelinePort;
  readonly channels: ChannelPort;
}

/**
 * 并发门：同时在飞的 dry-run 上限（提案 B5）。实例字段而非模块级计数——模块级 let 是门禁红线，
 * 状态必须收进实例（ProbeEndpoints 每挂载一份门，计数器与真实投递的节奏表相互独立）。
 */
export class DryRunGate {
  private active = 0;

  constructor(private readonly max: number = DRY_RUN_MAX_INFLIGHT) {}

  /** 尝试占一个槽位：满了即 false（调用方回 429，不排队）。 */
  tryAcquire(): boolean {
    if (this.active >= this.max) return false;
    this.active += 1;
    return true;
  }

  /** 释放一个槽位：settle 与超时都要走这里（finally），不按子进程退出——否则泄漏（B7）。 */
  release(): void {
    if (this.active > 0) this.active -= 1;
  }

  /** 在飞计数：只给单测读，生产路径不按它做判断（判断只认 tryAcquire 的原子结果）。 */
  get inflight(): number {
    return this.active;
  }
}

/**
 * 执行一次 dry-run：抛 DryRunInputError（调用方转 400），其余异常一律冒给预算层
 * （调用方按 500 收口，不记日志——禁写面）。成功即 B3 schema 的同步结果。
 */
export async function executeDryRun(
  deps: DryRunDeps,
  channelId: string,
  draft: unknown,
): Promise<DryRunResult> {
  const secrets = deps.config.readConfig().channels;
  const resolved = deps.config.resolveDraftChannels(draft, secrets);
  if (!resolved.ok) throw new DryRunInputError(resolved.hint);
  const effective = deps.config.normalizeConfig({ channels: [...resolved.channels] });
  const channel = effective.channels.find((item) => channelIdOf(item) === channelId);
  if (channel === undefined) {
    throw new DryRunInputError("draft.channels 里没有 channelId 对应的完整条目：" + channelId);
  }
  const message = deps.pipeline.finalizeRequest({ ...TEST_NOTIFICATION }, Date.now());
  const target = buildTarget(deps.pipeline, channel);
  const delivery = await deps.channels.dryRunTarget(target, message);
  if (delivery.status === "ok") return { ok: true, channelId, status: "ok" };
  return { ok: true, channelId, status: delivery.status, reason: toReason(delivery.reason) };
}

/**
 * 目标直构：映射复用路由的四个 builder（同一份，不漂移），门全部 bypass——
 * enabled 不看（直构），kind 取固定的 test（路由收窄不参与），frames / logger 接空实现
 * （browser 不 emit 真通知，system 的失败细节只进 reason.detail 不进日志）。
 */
function buildTarget(pipeline: PipelinePort, channel: EffectiveConfig["channels"][number]) {
  const quiet = { frames: { emit: () => {} }, logger: { warn: (_message: string): void => {} } };
  switch (channel.type) {
    case "bark":
      return pipeline.barkTarget(channel, "test");
    case "webhook":
      return pipeline.webhookTarget(channel);
    case "browser":
      // 内置 builder 回的是带身份的 RoutedTarget：dry-run 的身份即入参 channelId，只取其中的 target。
      return pipeline.browserTarget(channel, quiet, "test").target;
    case "system":
      return pipeline.systemTarget(channel, quiet).target;
    default:
      throw new DryRunInputError("未知的频道类型：" + String((channel as { type?: unknown }).type));
  }
}

/**
 * 投递理由 → 结果线形态：只做形状收窄。截断与收编是 dryRunTarget 的出站契约
 * （见 channels/interface.ts 的 dryRunTarget 注释），这里不再截第二遍——多截一次
 * 就多一条 api→channels 的跨模块值边（目录门面判红，见 verify-dir-imports）。
 */
function toReason(reason: ProducedReason): DryRunReason {
  const out: { code: string; params?: Record<string, string | number>; detail?: string } = {
    code: reason.code,
  };
  if (reason.params !== undefined) out.params = { ...reason.params };
  if (reason.detail !== undefined) out.detail = reason.detail;
  return out;
}

/**
 * 总预算：15s 内未 settle 即按超时拒绝（调用方回 408）。超时不取消在飞的投递——
 * bark / webhook 的单跳各有自己的 fetch 超时，system 的 spawn 靠出口的 KILL 8s 回收，
 * 它们结算后写不进任何地方（无 stores 引用），结果自然丢弃（B7「abort 残留声明」）。
 */
export function withDryRunBudget<T>(work: Promise<T>): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new DryRunTimeoutError("dry-run 超过 15s 总预算")),
      DRY_RUN_BUDGET_MS,
    );
    timer.unref();
    work.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (cause: unknown) => {
        clearTimeout(timer);
        reject(cause instanceof Error ? cause : new Error(String(cause)));
      },
    );
  });
}

/** api 域流块：SSE 连接、序号与断线补拉（共享层枢纽只管连接表、心跳与主动回收）。**序号**持久化在 `seq.json` 且重启后
 * 接着数——重置会让重连客户端把旧帧当新的，表现为「偶尔少一条通知」；**补拉**走 `?since=N`（EventSource 自动重连不带 query）。 */
import type { IncomingMessage, ServerResponse } from "node:http";
import {
  createSseHub,
  type SseEvictStats,
  type SseHub,
} from "../../../../../../../shared/sse-hub.js";
import {
  readTextFileSync,
  writeTextAtomic,
  SEQ_FILE_NAME,
  notifierFile,
} from "../../../shared/interface.ts";
import type { OutgoingFrame } from "../../deps.ts";
import type { StreamDeps, StreamEvent } from "./type.ts";

/** 补拉缓冲上限（条）：断线重连能回放的窗口，超出后只能从最新开始接。 */
const REPLAY_LIMIT = 200;

/** 心跳间隔（毫秒）：与客户端 60s 看门狗对齐，留足两次失败的余地。 */
const HEARTBEAT_MS = 30000;

/** 开流锚点。注释帧客户端不解析，它的作用是**立即 flush 响应头**：Node 会缓冲响应头直到第一次写入，没有这一行，
 * 客户端要等到第一个心跳（30s 后）才从 CONNECTING 进入 OPEN。 */
const CONNECTED = ": connected\n\n";

/** 线协议里的通知事件（`ping` 之外的那一支）。 */
type NotifyEvent = Extract<StreamEvent, { type: "notify" }>;

/** 未装配时的占位。占位值不会被真正读到（`installed` 守卫），它的作用是让字段有确定的类型、不必每个使用点判空。 */
const UNINSTALLED: StreamDeps = {
  logger: { warn: () => {} },
};

/** 未装配的枢纽：连接表为空，`dispose` 幂等。返回形状必须与真实枢纽逐键一致，否则「未装配」与
 * 「已装配但一条都没淘汰」在 `/health` 上长得不一样。 */
const UNINSTALLED_HUB: SseHub = {
  register: () => {},
  broadcast: () => {},
  size: () => 0,
  evictStats: () => ({
    close: 0,
    error: 0,
    stalled: 0,
    maxage: 0,
    destroyed: 0,
    dispose: 0,
  }),
  connHealth: () => [],
  dispose: () => {},
};

/** 流枢纽：连接表在共享层，序号与补拉在本块。 */
class StreamHub {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 装配入参（失败出口）。 */
  private deps: StreamDeps = UNINSTALLED;
  /** 枢纽：心跳与回收由共享层跑。 */
  private hub: SseHub = UNINSTALLED_HUB;
  /** 单调序号：上次进程留下的值往后接着数。 */
  private seq = 0;
  /** 补拉缓冲：只留最近 `REPLAY_LIMIT` 条。 */
  private replay: StreamEvent[] = [];
  /** 序号落盘位置：DSH home 由环境决定、进程内不变，故随实例一次性定下。 */
  private readonly file = notifierFile(SEQ_FILE_NAME);

  /** 装配：读回上次的序号，建起连接表与心跳。 */
  install(deps: StreamDeps): void {
    if (this.installed) throw new Error("dsh-notifier: api 流只能装配一次");
    this.installed = true;
    this.deps = deps;
    this.seq = readSeq(this.file);
    this.hub = createSseHub({
      heartbeatMs: HEARTBEAT_MS,
    });
  }

  /** 卸载：停心跳、关连接、忘掉缓冲。序号留在盘上，下次接着数。 */
  release(): void {
    this.hub.dispose();
    this.hub = UNINSTALLED_HUB;
    this.replay = [];
    this.installed = false;
  }

  /** 当前连接数。语义是**服务端未释放的句柄数**，不是「在线设备数」：两者混起来会让刷新页面的残留句柄看起来像多了
   * 一台设备。 */
  size(): number {
    return this.hub.size();
  }

  /** 回收原因计数：`/health` 的 `sseEvicts` 观测面（常量大小的聚合）。per-conn 明细（`connHealth`）
   * 故意不上去——它随连接数增长，而 `/health` 经 lan-proxy 对局域网可见。 */
  evictStats(): SseEvictStats {
    return this.hub.evictStats();
  }

  /** GET /events：接上一条 SSE 连接，并回放 `?since` 之后的帧。 */
  handle(req: IncomingMessage, res: ServerResponse): void {
    if (!this.installed) {
      res.writeHead(503);
      res.end();
      return;
    }
    res.writeHead(200, {
      "content-type": "text/event-stream; charset=utf-8",
      "cache-control": "no-store",
      connection: "keep-alive",
      // 反代缓冲会把 SSE 攒成一次性大响应，客户端看起来像「连上了但一直没消息」。
      "x-accel-buffering": "no",
    });
    res.write(CONNECTED);
    for (const event of this.since(sinceOf(req))) res.write(encode(event));
    this.hub.register(res);
  }

  /**
   * 广播一条通知帧：翻成线协议 → 编号 → 入缓冲 → 落序号 → 推给所有连接。翻译（`body`→`message`、
   * `pop`→`playOnly`）在这里而不在裁决管线：线协议是**浏览器出口**的约定，管线对外给的是内部帧，
   * 翻译上移会让内部词汇被线协议反向锁死。
   */
  publish(payload: OutgoingFrame): void {
    if (!this.installed) return;
    this.seq += 1;
    const { frame } = payload;
    const event: NotifyEvent = {
      type: "notify",
      seq: this.seq,
      kind: payload.kind,
      title: frame.title,
      message: frame.body,
      ts: Date.now(),
      sound: frame.sound,
      // 可见性判定归浏览器出口，帧自描述：客户端拿到就能执行，不必回查自己那份可能已过期的配置快照。
      whenVisible: frame.whenVisible,
    };
    // 缺席而不是 `false`：客户端判的是 `=== true`，而缺席让不认识这个字段的旧客户端收到的帧
    // 与从前逐字节一致。
    if (!frame.pop) event.playOnly = true;
    this.replay.push(event);
    if (this.replay.length > REPLAY_LIMIT) this.replay.splice(0, this.replay.length - REPLAY_LIMIT);
    // 序号是 fire-and-forget：写失败只让下次重启回退几条，不值得挡住广播。
    void writeTextAtomic(this.file, `${this.seq}\n`);
    this.hub.broadcast(encode(event));
  }

  /** 序号大于 `since` 的帧，按序。 */
  private since(value: number): StreamEvent[] {
    return this.replay.filter((event) => event.type === "notify" && event.seq > value);
  }
}

/** 一帧的 SSE 文本：`data:` 行加空行结束（客户端按 `onmessage` 收）。 */
function encode(event: StreamEvent): string {
  return `data: ${JSON.stringify(event)}\n\n`;
}

/** 从请求 URL 取 `?since=`；缺失或非法一律当 0（= 回放整个缓冲）。 */
function sinceOf(req: IncomingMessage): number {
  const query = (req.url ?? "").split("?")[1];
  if (query === undefined) return 0;
  const raw = new URLSearchParams(query).get("since");
  if (raw === null) return 0;
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
}

/** 读回上次进程留下的序号；文件缺失或内容不是正数都从 0 起算。 */
function readSeq(file: string): number {
  const read = readTextFileSync(file);
  if (!read.ok) return 0;
  const parsed = Number.parseInt(read.text.trim(), 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
}

/** 本域唯一的流实例：类不外放，外面 `new` 不出第二份序号。 */
export const streamHub = new StreamHub();

/**
 * api 域历史与频道状态端点。两者都是「读持久事实」：历史是通知的流水，状态是各频道最近一次投递
 * 终态；滚动、按天过滤、损坏行跳过都由 stores 域兜住，本域只做形状转换。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import type { StorePort } from "../../deps.ts";
import { sendJson } from "../route/index.ts";
import type { RouteHandler } from "../route/type.ts";

/** 历史与状态端点。能力在装配期接上，此后每个请求只读实例字段。 */
export class JournalEndpoints {
  constructor(private readonly stores: StorePort) {}

  /** GET /history：最近记录（截断与倒序由客户端做，它要的条数由界面决定）。 */
  readonly read: RouteHandler = async (
    _req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    sendJson(res, 200, { ok: true, records: await this.stores.readHistory() });
  };

  /** DELETE /history：清空，返回被清空条数（键名 `removed` 是客户端锁定的契约）。 */
  readonly clear: RouteHandler = async (
    _req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    sendJson(res, 200, { ok: true, removed: await this.stores.clearHistory() });
  };

  /** GET /status：各频道最近一次投递终态。 */
  readonly readStatus: RouteHandler = async (
    _req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    sendJson(res, 200, { ok: true, channels: await this.stores.readStatus() });
  };
}

/**
 * api 域动态种类端点：清单与确认。两个动作都走 sdk 域的管理面，本块不自己读设置、不自己写名单——确认态的写入
 * 路径只能有一条，写两份的表现是「设置页上点了允许，通知还是不发」。存在性在本块判（未登记 → 404）。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { readJsonBody } from "../../../../../../../shared/host-utils.js";
import type { KindPort } from "../../deps.ts";
import { sendFailure, sendJson } from "../route/index.ts";
import type { RouteHandler } from "../route/type.ts";
import type { KindPatchRequest } from "./type.ts";

/** 请求体上限（字节）：它最多带一个种类 id 与一个布尔。 */
const BODY_LIMIT = 4 * 1024;

/** 写面结果：不额外请 sdk 域导出名字，它的形状经能力面的签名可达。 */
type ConfirmOutcome = Awaited<ReturnType<KindPort["confirmKind"]>>;

/** 动态种类端点。能力在装配期接上，此后每个请求只读实例字段。 */
export class KindsEndpoints {
  constructor(private readonly kinds: KindPort) {}

  /** GET /kinds：清单（登记项 × 确认态）。 */
  readonly read: RouteHandler = (_req: IncomingMessage, res: ServerResponse): void => {
    sendJson(res, 200, { ok: true, kinds: this.kinds.listKinds() });
  };

  /**
   * POST /kinds：确认 / 撤销一个动态种类。四态逐态映射而不是压成一两个状态码（未登记 404、
   * 参数非法 400、版本冲突 409、服务不可用 503）——压扁之后用户看到的就只剩「操作失败」。
   * 成功体带回**新修订号**：客户端确认之后要同步自己那份 meta，否则紧接着的一次保存会拿着旧
   * 修订号提交、凭空造出一次冲突，而用户会以为自己刚才的确认没生效。
   */
  readonly confirm: RouteHandler = async (
    req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    const raw = await readJsonBody(req, BODY_LIMIT);
    if (raw === undefined) {
      sendFailure(res, 400, {
        code: "invalid-json",
        details: "请求体不是合法 JSON 对象（或超出大小上限）",
      });
      return;
    }
    // 断言只声明「这里有这两个字段」，不校验它们是什么——校验是紧接着的一步。
    const body = raw as KindPatchRequest;
    const kind = body.kind;
    const confirmed = body.confirmed;
    if (typeof kind !== "string" || kind.length === 0 || typeof confirmed !== "boolean") {
      sendFailure(res, 400, {
        code: "invalid",
        details: "需为 { kind: string, confirmed: boolean }",
      });
      return;
    }
    if (!this.kinds.listKinds().some((entry) => entry.id === kind)) {
      sendFailure(res, 404, { code: "not-found", details: `未注册的动态种类: ${kind}` });
      return;
    }
    respond(res, this.kinds, await this.kinds.confirmKind(kind, confirmed));
  };
}

/**
 * 写面结果 → 响应。与设置端点同款映射：同一个写面出来的失败，在两个端点上给出不同的答复，
 * 只会让客户端按路径分叉处理同一件事。
 */
function respond(res: ServerResponse, kinds: KindPort, result: ConfirmOutcome): void {
  if (result.ok) {
    sendJson(res, 200, { ok: true, kinds: kinds.listKinds(), revision: result.view.revision });
    return;
  }
  if (result.reason === "invalid") {
    sendFailure(res, 400, { error: `配置校验失败: ${result.error.key}`, hint: result.error.hint });
    return;
  }
  if (result.reason === "conflict") {
    // 客户端按 `code` 分流而不是按文案：文案会翻译，code 不会。
    sendFailure(res, 409, { error: "版本冲突", code: "SETTINGS_CONFLICT" });
    return;
  }
  sendFailure(res, 503, { error: "设置服务不可用", code: "settings-unavailable" });
}

/** api 域 probe 块 dry-run 的形状与预算常量。 */
import type { NotifyRequest, RawSettingValue } from "../../../deps.ts";

/** 测试通知的固定文案。不引入自由文本面：它验证的是链路本身而不是文案；取值沿用重写前的文案，
 * 用户看到的那两句不该因为一次内部重构而变（原先住在 probe/index.ts，dry-run 与老路共用，收到此处只留一份）。 */
export const TEST_NOTIFICATION: NotifyRequest = {
  kind: "test",
  title: "DSH：测试通知",
  body: "通知链路工作正常（此通知来自测试按钮）",
};

/** dry-run 结果状态：与 DeliverResult 同值（ok 无理由，failed/skipped 带理由）。 */
export type DryRunStatus = "ok" | "failed" | "skipped";

/** dry-run 结果里的理由：结构化理由的线形态（code + 标量 params + 宿主原文 detail）。 */
export interface DryRunReason {
  readonly code: string;
  readonly params?: Record<string, string | number>;
  readonly detail?: string;
}

/**
 * dry-run 结果（提案 B3 schema）：ok 恒 true（投递失败是结果里的 status，不是请求失败），
 * channelId 回显测的是谁，status 为此次实测结论，reason 只在非 ok 时出现（已截断+收编）。
 * 同步返回，不写 history / status，不推进 revision。
 */
export interface DryRunResult {
  readonly ok: true;
  readonly channelId: string;
  readonly status: DryRunStatus;
  readonly reason?: DryRunReason;
}

/** 服务端总预算（毫秒）：提案 B7，超时即 408，结果丢弃（在飞的投递无法撤回，见预算注释）。 */
export const DRY_RUN_BUDGET_MS = 15_000;

/** 并发帽：提案 B5，同时最多 2 个 dry-run，超限 429（不排队，面板提示手动重试）。 */
export const DRY_RUN_MAX_INFLIGHT = 2;

/** dry-run 请求里的 draft 形态：只认 channels（B1），其它顶层键与 revision 由调用方忽略。 */
export interface DryRunDraftShape {
  readonly channels?: RawSettingValue;
}

/** 输入错误（→ 400）：draft 非法、掩码无源、目标不在草稿里。永不经过路由收口（那会记 warn）。 */
export class DryRunInputError extends Error {}

/** 预算超时（→ 408）：15s 内未 settle，结果丢弃，槽位释放。 */
export class DryRunTimeoutError extends Error {}

/** api 域自检端点：发测试通知、报宿主平台。测试通知走的是**同一条**裁决管线（能力面的 `submit`），不另开旁路——
 * 否则「测试能响、真实事件不响」这类问题会被测试本身掩盖掉。 */
import type { IncomingMessage, ServerResponse } from "node:http";
import {
  type JsonBodyInvalidReason,
  readJsonBodyOutcome,
} from "../../../../../../../shared/host-utils.js";
import type {
  ChannelPort,
  ConfigPort,
  HostCapabilities,
  LoggerPort,
  PipelinePort,
} from "../../deps.ts";
import { sendFailure, sendJson } from "../route/index.ts";
import type { RouteHandler } from "../route/type.ts";
import { streamHub } from "../stream/index.ts";
import { DryRunGate, executeDryRun, withDryRunBudget } from "./dry-run/index.ts";
import { DryRunInputError, DryRunTimeoutError, TEST_NOTIFICATION } from "./dry-run/type.ts";
import type { TestRequest } from "./type.ts";

/**
 * 请求体上限（字节）：16K，与 settings 端对齐（提案 B5）。draft 里带模板与自定义头时
 * 体积天然以此为界（B4「模板头体积以 BODY_LIMIT 为界」，无单字段上限）；超限 400 复用
 * invalidBodyDetail。无 draft 的老路不受影响（原来几十字，最多一个频道 id）。
 */
const BODY_LIMIT = 16 * 1024;

/** 畸形 body 的回应文案：与 settings/kinds 的 invalid-json 同族，并把成因说清（客户端会展示 details）。 */
function invalidBodyDetail(reason: JsonBodyInvalidReason, limit: number): string {
  if (reason === "too-large") return `请求体超出大小上限（${limit} 字节）`;
  if (reason === "not-object") return "请求体必须是 JSON 对象";
  if (reason === "unreadable") return "请求体读取失败";
  return "请求体不是合法 JSON";
}

/**
 * 能力自检的总预算（毫秒）。探测是串行的（先跑平台命令探测，再逐个试 D-Bus CLI），单次超时叠加起来
 * 最坏可以到十几秒，而 `/health` 是「随时可打」的探活面——超过预算就如实回「无法判定」，并且把这条
 * 结论缓存下来：不缓存会让每个请求都重新等一遍，那是拿用户机器当靶场。
 */
const CAPABILITY_BUDGET_MS = 8000;

/** 给一个 Promise 套总预算；超时即拒绝（调用方按「无法判定」兜底）。 */
function withBudget<T>(work: Promise<T>, ms: number): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`能力自检超出 ${ms}ms 预算`)), ms);
    // 预算是兜底不是任务：它不该拖住进程退出（测试里尤其明显）
    timer.unref();
    work.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (cause: unknown) => {
        clearTimeout(timer);
        reject(cause instanceof Error ? cause : new Error(String(cause)));
      },
    );
  });
}

/** 自检端点。能力在装配期接上，此后每个请求只读实例字段。 */
export class ProbeEndpoints {
  /** 能力自检的共享缓存。两条路由共用同一次探测：探测会起子进程，每请求各探一次就是拿用户机器当靶场。 */
  private hostCapabilities?: Promise<HostCapabilities>;

  /** dry-run 并发门：实例字段（与真实投递的节奏表相互独立，见 DryRunGate）。 */
  private readonly dryRunGate = new DryRunGate();

  constructor(
    private readonly pipeline: PipelinePort,
    private readonly channels: ChannelPort,
    private readonly logger: LoggerPort,
    private readonly config: ConfigPort,
  ) {}

  /**
   * 取（必要时首次发起）能力自检。
   *
   * 兜底必须在**这里**：`/health` 是探活面，探测失败若继续往上抛，端点会连 `ok`/`platform`/`sseEvicts`
   * 一起丢掉，一个诊断附属面把主面拖成 500——那比「暂时不知道宿主能力」糟得多。
   */
  private capabilities(): Promise<HostCapabilities> {
    this.hostCapabilities ??= this.probeWithinBudget();
    return this.hostCapabilities;
  }

  private async probeWithinBudget(): Promise<HostCapabilities> {
    try {
      return await withBudget(this.channels.probeCapabilities(), CAPABILITY_BUDGET_MS);
    } catch (cause) {
      const reason = cause instanceof Error ? cause.message : String(cause);
      this.logger.warn(`dsh-notifier: 能力自检未给出结论（${reason}），按「无法判定」上报`);
      return this.channels.undeterminedCapabilities();
    }
  }

  /**
   * POST /test：造一条 `test` 通知交给裁决管线。只承诺「已受理」：`submit` 不返回结果，投递结果
   * 要去频道状态里看。响应里的 `sseConnections` 是**服务端未释放的句柄数**而不是投递计数——两者
   * 混起来，会让「测试发出去了但计数没动」这种正常现象看起来像故障。
   */
  readonly test: RouteHandler = async (
    req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    const outcome = await readJsonBodyOutcome(req, BODY_LIMIT);
    // body 可选（缺席 = 全频道测试），但**畸形 body 不等于「没有 body」**：这个端点有副作用，
    // 把截断的半包、超限体、非对象 JSON 当缺省处理，等于拿垃圾输入真发一条通知出去。
    if (outcome.kind === "invalid") {
      sendFailure(res, 400, {
        code: "invalid-json",
        details: invalidBodyDetail(outcome.reason, BODY_LIMIT),
      });
      return;
    }
    const body = (outcome.kind === "json" ? outcome.value : {}) as TestRequest;
    const channelId = body.channelId;
    if (channelId !== undefined && (typeof channelId !== "string" || channelId.length === 0)) {
      sendFailure(res, 400, {
        error: "测试通知参数非法",
        details: "channelId 必须为非空字符串或省略",
      });
      return;
    }
    // draft 出现即草稿测试（dry-run）：测眼前草稿、同步返回结果，全程零落盘。
    // 无 draft 时走老路（已保存配置的广播 / onlyChannel），语义一个字不改。
    if (body.draft !== undefined) {
      await this.testDraft(res, channelId, body.draft);
      return;
    }
    this.pipeline.submit(
      channelId === undefined
        ? TEST_NOTIFICATION
        : { ...TEST_NOTIFICATION, onlyChannel: channelId },
    );
    sendJson(res, 200, { ok: true, sseConnections: streamHub.size() });
  };

  /**
   * POST /test 的 dry-run 分支：单频道实测，同步返回 B3 schema。
   *
   * 禁写面落实在本函数：400 / 408 / 429 / 500 全部经 sendFailure / sendJson 直接回，
   * 永不调 logger（含路由收口的 500 兜底——execute 只抛 DryRunInputError 与预算超时，
   * 其余异常在这里就地收成固定文案的 500，不进日志）；stores / frames 本就没有入参，
   * 结构上够不着。槽位按 settle / 超时释放（finally），不按子进程退出（B7）。
   */
  private readonly testDraft = async (
    res: ServerResponse,
    channelId: unknown,
    draft: unknown,
  ): Promise<void> => {
    if (typeof channelId !== "string" || channelId.length === 0) {
      sendFailure(res, 400, {
        error: "草稿测试参数非法",
        details: "dry-run 只测单个频道：channelId 必须为非空字符串",
      });
      return;
    }
    if (!this.dryRunGate.tryAcquire()) {
      sendFailure(res, 429, {
        code: "dry-run-busy",
        error: "草稿测试并发已满，请稍后手动重试",
        details: "同时最多 2 个 dry-run（不排队）",
      });
      return;
    }
    try {
      const result = await withDryRunBudget(
        executeDryRun(
          { config: this.config, pipeline: this.pipeline, channels: this.channels },
          channelId,
          draft,
        ),
      );
      sendJson(res, 200, result);
    } catch (cause) {
      if (cause instanceof DryRunInputError) {
        sendFailure(res, 400, {
          error: "草稿测试参数非法",
          details: cause.message,
        });
      } else if (cause instanceof DryRunTimeoutError) {
        sendFailure(res, 408, {
          code: "dry-run-timeout",
          error: "草稿测试超时（15s），结果已丢弃",
          details: "在飞的投递无法撤回：若对方实际收到了，它不会出现在历史与状态里",
        });
      } else {
        sendFailure(res, 500, { error: "草稿测试内部错误" });
      }
    } finally {
      this.dryRunGate.release();
    }
  };

  /**
   * GET /health：宿主平台 + 连接回收计数 + 能力面**摘要**。平台值供客户端写系统通道提示（不能拿浏览器 OS 猜）；
   * `sseEvicts` 是 README 承诺的 churn 排障面——只有聚合计数（常量大小），per-conn 明细不上这里。
   * 能力面同样只给结论与维度状态（常量大小），明细（探测了哪些维度、缺哪个包）归 `/diagnostics`。
   */
  readonly health: RouteHandler = async (
    _req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    const host = await this.capabilities();
    sendJson(res, 200, {
      ok: true,
      plugin: "dsh-notifier",
      platform: this.channels.hostPlatform(),
      sseEvicts: streamHub.evictStats(),
      capabilities: { host: hostSummary(host) },
    });
  };

  /** GET /diagnostics：完整探测面。与 `/health` **共用同一次探测**，不在这里各探各的。 */
  readonly diagnostics: RouteHandler = async (
    _req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    const host = await this.capabilities();
    sendJson(res, 200, {
      ok: true,
      plugin: "dsh-notifier",
      platform: this.channels.hostPlatform(),
      capabilities: { host },
    });
  };
}

/** `/health` 的能力面摘要：只留结论与维度状态。`checked`/`players`/`remediation` 不上聚合面。 */
function hostSummary(host: HostCapabilities): unknown {
  return {
    verdict: host.verdict,
    unknownDimensions: host.unknownDimensions,
    popup: { state: host.popup.state },
    sound: { state: host.sound.state },
  };
}

/**
 * api 域路由块：注册端点并给每条请求套上围栏——回环围栏（非回环一律 403，必须用共享层默认参数：放行 `no-cors` 的开关
 * 只给资源伺服路由）、方法围栏（方法不在表里给 405 而不是 404）、异常收口（漏出去的异常留下的不是错误页，是一个挂住的连接）。
 */
import type { ServerResponse } from "node:http";
import { isLoopbackRequest } from "../../../../../../../shared/loopback.js";
import { REFUSAL_CODES } from "../../../../shared/interface.ts";
import type { RefusalCode } from "../../../../shared/interface.ts";
import type { LoggerPort, RegisterRoute } from "../../deps.ts";
import type { Endpoint, HttpMethod } from "./type.ts";

/**
 * 写一个 JSON 响应。泛型而不是固定形状：响应体有设置视图、历史数组、状态表各不相同的形状，
 * 而序列化只关心它能被 JSON 表达。
 */
export function sendJson<T>(
  res: ServerResponse,
  status: number,
  body: T,
  headers: Record<string, string> = {},
): void {
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "cache-control": "no-store",
    ...headers,
  });
  res.end(JSON.stringify(body));
}

/**
 * 失败负载。三个字段分开不是冗余：客户端把 `error` 当提示文本、把 `code` 当分流依据（版本冲突靠
 * `SETTINGS_CONFLICT` 判，不靠中文文案），`details` 给结构化细节——合成一个字符串就等于让客户端
 * 去匹配文案，而文案是本地化的。
 */
interface FailureBody {
  /** 面向用户的失败原因。 */
  error?: string;
  /** 结构化细节（请求体非法等）。 */
  details?: string;
  /** 补充说明（如合法取值范围）；客户端不读它，用它的是直接看响应的排查者。 */
  hint?: string;
  /** 机器可判的失败类别。 */
  code?: string;
}

/** 写一个失败响应：`{ ok: false, error: {...} }`，与端点的成功体同族。 */
export function sendFailure(
  res: ServerResponse,
  status: number,
  failure: FailureBody,
  headers: Record<string, string> = {},
): void {
  sendJson(res, status, { ok: false, error: failure }, headers);
}

/** 围栏拒绝体：`error` 是**裸字符串**，与端点失败体的对象形状不同，这是刻意的——旧客户端读失败提示的顺序是
 * 「`details` → `error` → `HTTP <status>`」，而它识别局域网直连只认最后那条兜底里的状态码。把 403 包成对象，
 * 提示文案就会变成「非回环请求」、状态码消失，「请改用 https 访问」的引导随之失效。
 *
 * `code` / `status` 是与 `error` 并列的**新增 sibling 字段**（#769）：新客户端按结构化字段分流，
 * 不再依赖「服务端必须永远保持 `error` 为裸字符串」这条隐式契约；旧客户端读不到它们，行为不变。
 * 因此三者共存，而不是把 `error` 升级成对象——后者会让新旧客户端都退到兜底路径上去。
 * `allow` 不进 body：它已是 405 的标准头（同一份事实两处声明，就有两处先腐烂）。 */
function sendRefused(
  res: ServerResponse,
  status: number,
  code: RefusalCode,
  reason: string,
  headers: Record<string, string> = {},
): void {
  sendJson(res, status, { error: reason, code, status }, headers);
}

/** 注册端点组，返回摘除器清单（与装配顺序相反地释放）。 */
export function registerEndpoints(
  register: RegisterRoute,
  endpoints: Endpoint[],
  logger: LoggerPort,
): Array<() => void> {
  const disposers: Array<() => void> = [];
  for (const endpoint of endpoints) {
    disposers.push(
      register({
        kind: "exact",
        path: endpoint.path,
        handler: (req, res) => {
          if (!isLoopbackRequest(req)) {
            sendRefused(res, 403, REFUSAL_CODES.FORBIDDEN_LOOPBACK, "forbidden: loopback-only");
            return;
          }
          const handle = endpoint.methods[(req.method ?? "") as HttpMethod];
          if (handle === undefined) {
            // `allow` 是 405 该带的头，调用方不必回翻文档；状态码与文案仍与旧协议一致，
            // 新增的只是与之并列的机读 code/status。
            sendRefused(
              res,
              405,
              REFUSAL_CODES.METHOD_NOT_ALLOWED,
              `method not allowed: ${req.method}`,
              {
                allow: Object.keys(endpoint.methods).join(", "),
              },
            );
            return;
          }
          try {
            const done = handle(req, res);
            // 异步端点失败落在 promise、同步端点落在 catch：收口只有一处，但两条路都要接上，
            // 否则异步端点的异常会变成未捕获拒绝。
            if (done instanceof Promise) {
              done.catch((cause) => {
                reportFailure(res, logger, cause instanceof Error ? cause.message : String(cause));
              });
            }
          } catch (cause) {
            reportFailure(res, logger, cause instanceof Error ? cause.message : String(cause));
          }
        },
      }),
    );
  }
  return disposers;
}

/**
 * 异常收口：记日志并回 500。响应头可能已经发出（SSE 端点尤其如此），所以只在不曾写过时才补 500
 * ——重复写会抛 `ERR_HTTP_HEADERS_SENT`，把一次端点失败升级成宿主侧的未捕获异常。
 */
function reportFailure(res: ServerResponse, logger: LoggerPort, reason: string): void {
  logger.warn(`dsh-notifier: 浏览器端点处理失败 — ${reason}`);
  if (!res.headersSent) sendFailure(res, 500, { error: reason });
}

/**
 * api 域编排：把端点挂上宿主、把帧接进流，卸载时全部收回。端点表是本域对外的**完整承诺**（路径由客户端锁定，
 * 改一处就要两端同改）；它在装配期构造而不是模块级常量——写成常量各端点就得自己去别处找依赖，而症状是测试里换不掉真实现。
 */
import type { ApiDeps } from "../../deps.ts";
import { JournalEndpoints } from "../journal/index.ts";
import { KindsEndpoints } from "../kinds/index.ts";
import { ProbeEndpoints } from "../probe/index.ts";
import { registerEndpoints } from "../route/index.ts";
import type { Endpoint } from "../route/type.ts";
import { SettingsEndpoints } from "../settings/index.ts";
import { streamHub } from "../stream/index.ts";

/** 浏览器出口：路由注册与帧订阅的生命周期。 */
class ApiService {
  /** 是否已装配；单例实例重复装配是编程错误，当场暴露。 */
  private installed = false;
  /** 摘除器：路由与帧订阅混在一起，卸载时逐个调用。 */
  private disposers: Array<() => void> = [];

  /** 装配：挂路由、接帧。 */
  install(deps: ApiDeps): void {
    if (this.installed) throw new Error("dsh-notifier: api 域只能装配一次");
    this.installed = true;
    streamHub.install({ logger: deps.logger });

    const settings = new SettingsEndpoints(deps.config);
    const journal = new JournalEndpoints(deps.stores);
    const probe = new ProbeEndpoints(deps.pipeline, deps.channels, deps.logger, deps.config);
    const kinds = new KindsEndpoints(deps.kinds);
    const endpoints: Endpoint[] = [
      { path: "/api/dsh-notifier/config", methods: { GET: settings.read, PUT: settings.write } },
      { path: "/api/dsh-notifier/history", methods: { GET: journal.read, DELETE: journal.clear } },
      { path: "/api/dsh-notifier/status", methods: { GET: journal.readStatus } },
      { path: "/api/dsh-notifier/kinds", methods: { GET: kinds.read, POST: kinds.confirm } },
      { path: "/api/dsh-notifier/test", methods: { POST: probe.test } },
      { path: "/api/dsh-notifier/health", methods: { GET: probe.health } },
      { path: "/api/dsh-notifier/diagnostics", methods: { GET: probe.diagnostics } },
      // 包一层而不是裸传 streamHub.handle：那个方法要用 this，裸传会在回调时丢掉。
      {
        path: "/api/dsh-notifier/events",
        methods: { GET: (req, res) => streamHub.handle(req, res) },
      },
    ];

    this.disposers.push(
      ...registerEndpoints(deps.register, endpoints, deps.logger),
      deps.frames.onFrame((payload) => streamHub.publish(payload)),
    );
  }

  /** 卸载：摘路由、退订帧、停掉流。重复调用无害——卸载链可能走到不止一次。 */
  release(): void {
    for (const dispose of this.disposers) dispose();
    this.disposers = [];
    streamHub.release();
    this.installed = false;
  }
}

/** 本域唯一的编排实例：类不外放，外面 `new` 不出第二份路由表。 */
export const apiService = new ApiService();

/** api 域设置端点：读设置视图、写设置。写面把请求**形状**与设置**内容**分开把关——`patch` 是不是对象、
 * `expectedRevision` 是不是非负整数是线协议的事，本域判；字段值合不合法、掩码要不要还原由 config 域写面回答。 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { readJsonBody } from "../../../../../../../shared/host-utils.js";
import type { ConfigPort, RawSettingValue } from "../../deps.ts";
import { sendFailure, sendJson } from "../route/index.ts";
import type { RouteHandler } from "../route/type.ts";
import type { PatchRequest } from "./type.ts";

/** 请求体上限（字节）：设置是几百字节的 JSON，16KB 已远超合理值。 */
const BODY_LIMIT = 16 * 1024;

/** 写面结果：不额外请 config 域导出一个类型名，它的形状经能力面的签名可达。 */
type WriteOutcome = Awaited<ReturnType<ConfigPort["writeConfig"]>>;

/**
 * 设置端点。用类而不是返回闭包的工厂：闭包会把「这个处理函数从哪拿到 config 域」藏进词法环境，
 * 而类把它摊在构造签名上，于是「这个端点依赖什么」在文件里就能读到。
 */
export class SettingsEndpoints {
  constructor(private readonly config: ConfigPort) {}

  /** GET /config：一次取齐视图的四个事实（分开取会让界面拿旧修订号提交，凭空造出冲突）。 */
  readonly read: RouteHandler = (_req: IncomingMessage, res: ServerResponse): void => {
    sendJson(res, 200, { ok: true, ...this.config.readSettingsView() });
  };

  /**
   * PUT /config：写用户设置。四态逐态映射而不是压成一两个状态码：`invalid` 要让界面定位到出错的
   * 那一行，`conflict` 要触发「加载最新 / 覆盖提交」的恢复流程，`unavailable` 要把表单整体置灰
   * ——压扁之后用户看到的就只剩「保存失败」，而三种原因要做的事完全不同。
   */
  readonly write: RouteHandler = async (
    req: IncomingMessage,
    res: ServerResponse,
  ): Promise<void> => {
    const raw = await readJsonBody(req, BODY_LIMIT);
    if (raw === undefined) {
      sendFailure(res, 400, {
        code: "invalid-json",
        details: "请求体不是合法 JSON 对象（或超出大小上限）",
      });
      return;
    }
    // 断言只声明「这里有这两个字段」，不校验它们是什么——校验是紧接着的两步。
    const body = raw as PatchRequest;
    if (!isPatch(body.patch)) {
      sendFailure(res, 400, {
        error: "配置校验失败: patch",
        hint: "需至少包含一个配置键（patch 不能为空）",
      });
      return;
    }
    const patch = body.patch;
    const revision = body.expectedRevision;
    if (revision === undefined) {
      respond(res, await this.config.writeConfig(patch));
      return;
    }
    if (typeof revision !== "number" || !Number.isInteger(revision) || revision < 0) {
      sendFailure(res, 400, {
        error: "配置校验失败: expectedRevision",
        hint: "expectedRevision 必须为非负整数或省略",
      });
      return;
    }
    respond(res, await this.config.writeConfig(patch, revision));
  };
}

/** 提交体里的 `patch` 是不是一份可用的记录。不判形状就会被上面的断言一路放行：`{patch: "abc"}` 在设置域里是三个
 * 「陌生键」，而陌生键是刻意放行的（透传保留），于是一次非法请求会把 "0"/"1"/"2" 写进配置文件。空 patch 也归为不可用
 * ——它在设置域是一次「无变化的写」，在界面上却是一次点击，两者对不上时用户会以为这次保存丢了。 */
function isPatch(value?: RawSettingValue): value is { readonly [key: string]: RawSettingValue } {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  return Object.keys(value).length > 0;
}

/**
 * 写面结果 → 响应。成功体只回 `user` 与 `revision`：`effective` 是这次合并的结果，界面用自己刚
 * 提交的草稿就能推出来，多回一份只会多一个可能与本地草稿不一致的「服务端版本」。
 */
function respond(res: ServerResponse, result: WriteOutcome): void {
  if (result.ok) {
    sendJson(res, 200, { ok: true, user: result.view.user, revision: result.view.revision });
    return;
  }
  if (result.reason === "invalid") {
    sendFailure(res, 400, { error: `配置校验失败: ${result.error.key}`, hint: result.error.hint });
    return;
  }
  if (result.reason === "conflict") {
    // 客户端按 `code` 分流而不是按文案：文案会翻译，code 不会。
    sendFailure(res, 409, { error: "版本冲突", code: "SETTINGS_CONFLICT" });
    return;
  }
  sendFailure(res, 503, { error: "设置服务不可用", code: "settings-unavailable" });
}

