/**
 * dsh-notifier api 域 probe 块 —— POST /test 与 GET /health。
 *
 * 判据面：测试通知必须走**同一条**裁决管线（不另开旁路），否则「测试能响、真实事件不响」这类问题
 * 会被测试本身掩盖；响应里的 `sseConnections` 进的是客户端「已发送至 N 个页面」的提示，报假数就是
 * 骗用户；`/health` 报的是**宿主平台**，客户端据此写系统通道的平台提示，拿浏览器 OS 猜
 * 会让 Windows 用户看到 Linux 的安装引导。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { afterEach, describe, expect, it, vi } from "vitest";

import type {
  ChannelPort,
  ConfigPort,
  HostCapabilities,
  NotifyRequest,
  PipelinePort,
} from "../../../src/server/api/deps.ts";
import * as channelsApi from "../../../src/server/channels/interface.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import * as configApi from "../../../src/server/config/interface.ts";
import * as pipelineApi from "../../../src/server/pipeline/interface.ts";
import { ProbeEndpoints } from "../../../src/server/api/impl/probe/index.ts";
import { streamHub } from "../../../src/server/api/impl/stream/index.ts";
import { jsonReq, makeLogger, makeRes, wire } from "../../helpers.ts";

/** 假能力面：调用次数要能被数（缓存判据靠它），平台值可注入（三平台格靠它），探测结论可注入失败。 */
function fakeChannels(
  options: { hostPlatform?: () => string; probe?: () => Promise<HostCapabilities> } = {},
) {
  let calls = 0;
  const port: ChannelPort = {
    probeCapabilities: () => {
      calls += 1;
      return options.probe === undefined ? Promise.resolve(CAPABILITIES) : options.probe();
    },
    hostPlatform: options.hostPlatform ?? (() => "linux"),
    undeterminedCapabilities: () => UNDETERMINED,
    // dry-run 出站走真实实现（本文件不断言它，端口类型要求齐成员）。
    dryRunTarget: channelsApi.dryRunTarget,
  };
  return { port, probeCalls: () => calls };
}

/** `/health` 上「无法判定」的**摘要**形状：能力面摘要是完整面的投影，不是同一个对象。 */
const UNDETERMINED_SUMMARY = {
  verdict: "unknown",
  unknownDimensions: ["popup", "sound"],
  popup: { state: "unknown" },
  sound: { state: "unknown" },
};

/** 「无法判定」的兜底形状（与服务端 `undeterminedCapabilities()` 同形，独立抄写才守得住漂移）。 */
const UNDETERMINED: HostCapabilities = {
  verdict: "unknown",
  unknownDimensions: ["popup", "sound"],
  popup: { state: "unknown", checked: [] },
  sound: { state: "unknown", players: [], toneFileAvailable: false, checked: [] },
  remediation: [],
};

/** 完整能力面夹具（含明细）：摘要与完整面的差异必须能被断言。 */
const CAPABILITIES: HostCapabilities = {
  verdict: "degraded",
  unknownDimensions: ["popup"],
  popup: {
    state: "unknown",
    checked: ["notify-send", "dbus-name-owner", "dbus-activatable", "session-bus"],
  },
  sound: {
    state: "degraded",
    players: ["pw-play"],
    toneFileAvailable: false,
    checked: ["players", "tone-file"],
  },
  remediation: [{ code: "host-no-tone-file" }],
};

/** 假请求：body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(
  options: { method?: string; body?: unknown; rawBody?: string } = {},
): IncomingMessage {
  return jsonReq({
    method: options.method ?? "POST",
    url: "/api/dsh-notifier/test",
    body: options.body,
    rawBody: options.rawBody,
  });
}

/** 假裁决管线：只记下提交体（该不该发、发去哪都是管线的事）。
 * dry-run 直构件走真实实现（本文件不断言它们，端口类型要求齐成员）。 */
function fakePipeline() {
  const submitted: NotifyRequest[] = [];
  const port: PipelinePort = {
    submit: (request) => {
      submitted.push(request);
    },
    finalizeRequest: pipelineApi.finalizeRequest,
    barkTarget: pipelineApi.barkTarget,
    browserTarget: pipelineApi.browserTarget,
    systemTarget: pipelineApi.systemTarget,
    webhookTarget: pipelineApi.webhookTarget,
  };
  return { port, submitted };
}

/** dry-run 不用的配置面：读默认空配置，纯函数走真实实现（与 dry-run.test.ts 同源）。 */
function fakeConfig(): ConfigPort {
  return {
    readConfig: () => ({ ...DEFAULT_CONFIG }),
    readSettingsView: () => {
      throw new Error("本文件不读视图");
    },
    writeConfig: () => Promise.reject(new Error("本文件不写配置")),
    resolveDraftChannels: configApi.resolveDraftChannels,
    normalizeConfig: configApi.normalizeConfig,
  };
}

/** POST 一次测试通知（给定请求对象）。 */
async function postWith(req: IncomingMessage) {
  const pipeline = fakePipeline();
  const { res, rec, json } = makeRes();
  await new ProbeEndpoints(pipeline.port, fakeChannels().port, makeLogger(), fakeConfig()).test(
    req,
    res,
  );
  return { rec, json, pipeline };
}

/** POST 一次测试通知。 */
function post(request: { body?: unknown; rawBody?: string }) {
  return postWith(makeReq(request));
}

/** 块是字符串的请求（流被 `setEncoding` 过这类形态）：共享读取器承诺**不抛错**。 */
function makeStringChunkReq(): IncomingMessage {
  return {
    method: "POST",
    url: "/api/dsh-notifier/test",
    headers: { host: "127.0.0.1:3080" },
    socket: { remoteAddress: "127.0.0.1" },
    async *[Symbol.asyncIterator]() {
      yield '{"channelId":"bark:main"}';
    },
  } as unknown as IncomingMessage;
}

/** 读流中途出错的路由请求：客户端半途断开、socket 报错都长这样。 */
function makeBrokenReq(): IncomingMessage {
  return {
    method: "POST",
    url: "/api/dsh-notifier/test",
    headers: { host: "127.0.0.1:3080" },
    socket: { remoteAddress: "127.0.0.1" },
    async *[Symbol.asyncIterator]() {
      throw new Error("socket hang up");
    },
  } as unknown as IncomingMessage;
}

/**
 * 假 SSE 响应：连接表注册要 `on` / `destroyed` / `write` / `destroy`，其余方法用不到。
 *
 * 为什么要它：`sseConnections` 报的是服务端未释放的句柄数，未装配的枢纽恒为 0——断言里的
 * 字面量 0 因此恒真。真占住一个句柄才能把「报的是真实连接数」证伪。
 */
function makeSseRes(): ServerResponse {
  const rec = { destroyed: false };
  const res = {
    get destroyed() {
      return rec.destroyed;
    },
    get writableEnded() {
      return false;
    },
    writeHead() {
      return res;
    },
    write() {
      return true;
    },
    on() {
      return res;
    },
    destroy() {
      rec.destroyed = true;
    },
  };
  return res as unknown as ServerResponse;
}

afterEach(() => {
  streamHub.release();
});

describe("POST /test：测试通知走同一条裁决管线", () => {
  it("没有 body 时按全频道测试：提交固定的 test 文案，并报出服务端真实的 SSE 句柄数", async () => {
    streamHub.install({ logger: makeLogger() });
    streamHub.handle(makeReq({ method: "GET" }), makeSseRes());

    const { rec, json, pipeline } = await post({});
    expect(rec.status).toBe(200);
    expect(pipeline.submitted).toEqual([
      { kind: "test", title: "DSH：测试通知", body: "通知链路工作正常（此通知来自测试按钮）" },
    ]);
    expect(json()).toEqual({ ok: true, sseConnections: 1 });
  });

  it("带 channelId 时只多一个 onlyChannel（指定出口不能变成另一条通知文案）", async () => {
    const { pipeline } = await post({ body: { channelId: "bark:main" } });
    expect(pipeline.submitted).toEqual([
      {
        kind: "test",
        title: "DSH：测试通知",
        body: "通知链路工作正常（此通知来自测试按钮）",
        onlyChannel: "bark:main",
      },
    ]);
  });

  it.each<[string, unknown]>([
    ["空串", ""],
    ["数字", 42],
  ])("channelId 非法（%s）→ 400 且不提交", async (_label, channelId) => {
    const { rec, json, pipeline } = await post({ body: { channelId } });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { error: "测试通知参数非法", details: "channelId 必须为非空字符串或省略" },
    });
    expect(pipeline.submitted).toEqual([]);
  });
});

/**
 * 这个端点有副作用，所以「body 读不出来」不能退化成「没给 body」——后者会真的发一条通知出去。
 * 四类成因各自的文案都要落到响应里，客户端才能说清是体太大还是写错了。
 */
describe("POST /test：body 读不出来时 fail-closed（不许当成「没给 body」）", () => {
  it.each<[string, string, string]>([
    ["JSON 语法错", "{ not json", "请求体不是合法 JSON"],
    ["JSON 合法但是数字", "42", "请求体必须是 JSON 对象"],
    ["JSON 合法但是 null", "null", "请求体必须是 JSON 对象"],
  ])("%s → 400 invalid-json，一条都不提交", async (_label, rawBody, details) => {
    const { rec, json, pipeline } = await post({ rawBody });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({ ok: false, error: { code: "invalid-json", details } });
    expect(pipeline.submitted).toEqual([]);
  });

  it("超限体 → 400 invalid-json 且不提交：JSON 本身合法也不例外", async () => {
    // 上限 16K（与 settings 端对齐，PR-B）：超限体必须大于 16K 才触发 too-large。
    const { rec, json, pipeline } = await post({ body: { channelId: "a".repeat(20000) } });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体超出大小上限（16384 字节）" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("读流中断 → 400 invalid-json：半途断开不等于「没给 body」", async () => {
    const { rec, json, pipeline } = await postWith(makeBrokenReq());
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体读取失败" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("块不是 Buffer 时也不抛错：按「读不出来」落 400，异常不许打到调用方", async () => {
    const { rec, json, pipeline } = await postWith(makeStringChunkReq());
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体读取失败" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("纯空白 body 仍是「没给 body」：按全频道测试受理，不判畸形", async () => {
    const { rec, pipeline } = await post({ rawBody: "   \n\t " });
    expect(rec.status).toBe(200);
    expect(pipeline.submitted).toEqual([
      { kind: "test", title: "DSH：测试通知", body: "通知链路工作正常（此通知来自测试按钮）" },
    ]);
  });
});

describe("GET /health：报宿主平台、连接回收计数与能力面摘要", () => {
  it("platform 取 channels 域的平台事实（客户端据此写系统通道提示，不能拿浏览器 OS 猜），sseEvicts 形状与真实枢纽逐键一致", async () => {
    const { res, rec, json } = makeRes();
    const channels = fakeChannels({ hostPlatform: () => "darwin" });
    await new ProbeEndpoints(fakePipeline().port, channels.port, makeLogger(), fakeConfig()).health(
      makeReq({ method: "GET" }),
      res,
    );
    expect(rec.status).toBe(200);
    expect(json()).toEqual({
      ok: true,
      plugin: "dsh-notifier",
      // 端口注入的值而不是 process.platform：api 域直读进程全局会让这一格在 CI 上永远只有 linux 可达
      platform: "darwin",
      // 未装配占位：形状（键集）必须与真实枢纽一致，否则「未装配」与「装好但没淘汰过」在 /health 上长得不一样
      sseEvicts: {
        close: 0,
        error: 0,
        stalled: 0,
        maxage: 0,
        destroyed: 0,
        dispose: 0,
      },
      // 摘要：只给结论与维度状态，明细（checked / players / remediation）归 /diagnostics
      capabilities: {
        host: {
          verdict: "degraded",
          unknownDimensions: ["popup"],
          popup: { state: "unknown" },
          sound: { state: "degraded" },
        },
      },
    });
  });

  it("能力自检只探一次：连续两次请求共用同一个 Promise（每请求各探一次就是拿用户机器当靶场）", async () => {
    const channels = fakeChannels();
    const endpoints = new ProbeEndpoints(
      fakePipeline().port,
      channels.port,
      makeLogger(),
      fakeConfig(),
    );

    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);
    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);

    expect(channels.probeCalls()).toBe(1);
    // 摘要不得泄漏明细：客户端要靠 /diagnostics 才拿得到“下一步该干什么”
    const summary = makeRes();
    await endpoints.health(makeReq({ method: "GET" }), summary.res);
    expect(JSON.stringify(summary.json())).not.toContain("host-no-tone-file");
  });
});

describe("能力自检的兜底：诊断附属面不许把探活面拖下水", () => {
  it("探测抛错时 /health 不 500：既有键全在，能力面按「无法判定」上报并留恰好一条 warn", async () => {
    const channels = fakeChannels({ probe: () => Promise.reject(new Error("探测炸了")) });
    const logger = makeLogger();
    const endpoints = new ProbeEndpoints(fakePipeline().port, channels.port, logger, fakeConfig());
    const { res, rec, json } = makeRes();
    await endpoints.health(makeReq({ method: "GET" }), res);

    expect(rec.status).toBe(200);
    const body = wire<{ ok: boolean; platform: string; capabilities: { host: HostCapabilities } }>(
      json(),
    );
    expect(body.ok).toBe(true);
    expect(body.platform).toBe("linux");
    expect(body.capabilities.host).toEqual(UNDETERMINED_SUMMARY);
    expect(logger.warns).toHaveLength(1);

    // 失败结论同样进缓存：不缓存会让每个请求都重新等一遍注定失败的探测
    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);
    expect(channels.probeCalls()).toBe(1);
  });

  it("探测超过总预算即按「无法判定」上报（预算兜底必须真的会到点）", async () => {
    vi.useFakeTimers();
    try {
      const channels = fakeChannels({ probe: () => new Promise<HostCapabilities>(() => {}) });
      const endpoints = new ProbeEndpoints(
        fakePipeline().port,
        channels.port,
        makeLogger(),
        fakeConfig(),
      );
      const { res, json } = makeRes();
      const pending = endpoints.health(makeReq({ method: "GET" }), res);
      // 不引用具体预算值（引用它就等于把常量抄成第二份）：只要求它在 10s 内到点
      await vi.advanceTimersByTimeAsync(10_000);
      await pending;
      expect(wire<{ capabilities: { host: unknown } }>(json()).capabilities.host).toEqual(
        UNDETERMINED_SUMMARY,
      );
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("GET /diagnostics：完整探测面", () => {
  it("给的是 channels 域那一份完整能力面（checked / players / remediation 都在）", async () => {
    const { res, rec, json } = makeRes();
    const channels = fakeChannels();
    await new ProbeEndpoints(
      fakePipeline().port,
      channels.port,
      makeLogger(),
      fakeConfig(),
    ).diagnostics(makeReq({ method: "GET" }), res);
    expect(rec.status).toBe(200);
    const body = wire<{ platform: string; capabilities: { host: HostCapabilities } }>(json());
    expect(body.platform).toBe("linux");
    expect(body.capabilities.host).toEqual(CAPABILITIES);
    // 「响应体零原文」不在这层判：这里注入的是模块常量，`expect(JSON).not.toContain(...)` 结构上永远
    // 成立（一次实现改动都打不红）。真正的判据在域层——`remediation.params` 只由数据表产生，
    // 注入敌意 os-release 时域层用例会红。
  });
});

packages/dsh-notifier/test/unit/api/serv.source:
/**
 * dsh-notifier api 域 service 块 —— 装配面：路径表（对客户端的完整承诺）、接线、生命周期。
 *
 * 这一层只有装配面看得见的东西才值得测：哪 8 条路径被挂上、每条路径认哪些方法、四个端点各拿到
 * 的是哪份能力面（把 stores 接到设置端点是编译期拦不住的错位）、卸载时路由与帧订阅是否真的收回。
 * 单条端点的判据在各自的块里测，这里不重复。
 *
 * 隔离纪律：序号文件的路径在**模块加载期**就被 `streamHub` 定下（`notifierFile()` 在类字段
 * 初始化里跑，见 `impl/stream`）。故临时 `DSH_HOME` 必须先于 api 模块的导入建立——用顶层 await
 * 动态导入而不是静态导入，否则 `installApi` 会去读真实 `~/.dsh` 下的 `seq.json`。
 */
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { IncomingMessage, ServerResponse } from "node:http";
import { afterAll, afterEach, describe, expect, it } from "vitest";

import type { ApiDeps, HostCapabilities, OutgoingFrame } from "../../../src/server/api/deps.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import { jsonReq, makeLogger, makeRegister, pollUntil, tempDshHome, wire } from "../../helpers.ts";

const home = tempDshHome();
const { installApi, releaseApi } = await import("../../../src/server/api/interface.ts");
// 端口新增的 dry-run 纯函数走真实实现（动态导入与上同纪：config 单例的落盘路径在构造时定下）。
const { resolveDraftChannels, normalizeConfig } =
  await import("../../../src/server/config/interface.ts");
const { finalizeRequest, barkTarget, browserTarget, systemTarget, webhookTarget } =
  await import("../../../src/server/pipeline/interface.ts");
const { dryRunTarget } = await import("../../../src/server/channels/interface.ts");

/**
 * 客户端锁定的路径表（`src/client/index.tsx` 里的 URL 常量是同一份承诺）。独立写一遍而不是从源码
 * 导：改路径就要两端同改，两边都从同一个常量取的话，改一处会让两边一起变绿。
 */
const PATHS = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
] as const;

/** 能力面夹具：本文件只验「两个自检端点拿到的是 channels 域给的那一份」，形状细节归 api/probe 的用例。 */
const CAPABILITIES: HostCapabilities = {
  verdict: "degraded",
  unknownDimensions: [],
  popup: { state: "ok", checked: ["notify-send", "dbus-name-owner", "session-bus"] },
  sound: {
    state: "degraded",
    players: ["pw-play"],
    toneFileAvailable: false,
    checked: ["players", "tone-file"],
  },
  remediation: [{ code: "host-no-tone-file" }],
};

/** 路径 → 它认的方法。`allow` 头会把这行字逐条回给客户端，故它同时是 405 判据的期望值。 */
const METHOD_TABLE: ReadonlyArray<readonly [string, readonly string[]]> = [
  ["/api/dsh-notifier/config", ["GET", "PUT"]],
  ["/api/dsh-notifier/history", ["GET", "DELETE"]],
  ["/api/dsh-notifier/status", ["GET"]],
  ["/api/dsh-notifier/kinds", ["GET", "POST"]],
  ["/api/dsh-notifier/test", ["POST"]],
  ["/api/dsh-notifier/health", ["GET"]],
  ["/api/dsh-notifier/diagnostics", ["GET"]],
  ["/api/dsh-notifier/events", ["GET"]],
];

afterEach(() => {
  releaseApi();
});

afterAll(() => {
  home.dispose();
});

/** 假请求：合法回环，body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(options: { method?: string; url: string; body?: unknown }): IncomingMessage {
  return jsonReq({ method: options.method ?? "GET", url: options.url, body: options.body });
}

/** 假响应：JSON 端点与 SSE 端点共用（SSE 需要 `on`/`destroy` 才能被连接表收下）。 */
function makeRes() {
  const rec = {
    status: 0,
    headers: {} as Record<string, string>,
    text: "",
    headersSent: false,
    destroyed: false,
  };
  const listeners = new Map<string, Array<() => void>>();
  const res = {
    get headersSent() {
      return rec.headersSent;
    },
    get destroyed() {
      return rec.destroyed;
    },
    get writableEnded() {
      return false;
    },
    writeHead(status: number, headers?: Record<string, string>) {
      rec.status = status;
      rec.headers = { ...(headers ?? {}) };
      rec.headersSent = true;
      return res;
    },
    write(chunk: string) {
      rec.text += chunk;
      return true;
    },
    end(chunk?: string) {
      if (chunk !== undefined) rec.text += chunk;
      rec.headersSent = true;
      return res;
    },
    on(event: string, handler: () => void) {
      listeners.set(event, [...(listeners.get(event) ?? []), handler]);
      return res;
    },
    destroy() {
      rec.destroyed = true;
      for (const handler of listeners.get("close") ?? []) handler();
    },
  };
  return {
    res: res as unknown as ServerResponse,
    rec,
    json: (): Record<string, unknown> => JSON.parse(rec.text),
  };
}

/** 假帧入口：handler 捕获下来手动触发，退订记账。 */
function makeFrameInlet() {
  const handlers: Array<(payload: OutgoingFrame) => void> = [];
  let disposed = 0;
  return {
    handlers,
    disposedCount: () => disposed,
    port: {
      onFrame: (handler: (payload: OutgoingFrame) => void) => {
        handlers.push(handler);
        return () => {
          disposed += 1;
        };
      },
    },
  };
}

/** 各能力面返回带标记的值：端点回给我的标记来自哪一份面，一读就知道有没有接错线。 */
const HISTORY = [{ ts: 1, kind: "done", title: "历史", message: "正文" }];
const STATUS = { "bark:main": { lastTs: 1, lastStatus: "ok" as const, failStreak: 0 } };
const KINDS = [{ id: "demo:x", label: "X", confirmed: false }];

/** 装配一次 api 域，交出全部观测面。 */
function assemble() {
  const hub = makeRegister();
  const frames = makeFrameInlet();
  const logger = makeLogger();
  const submitted: Array<{ kind: string }> = [];
  const deps: ApiDeps = {
    register: hub.register,
    frames: frames.port,
    logger,
    config: {
      readConfig: () => ({ ...DEFAULT_CONFIG }),
      readSettingsView: () => ({
        user: { notifyAsk: false },
        revision: 7,
        writable: true,
        effective: { notifyAsk: false },
      }),
      writeConfig: async () => ({
        ok: true,
        view: { user: {}, revision: 8, writable: true, effective: {} },
      }),
      resolveDraftChannels,
      normalizeConfig,
    },
    stores: {
      readHistory: async () => [...HISTORY],
      clearHistory: async () => 2,
      readStatus: async () => ({ ...STATUS }),
    },
    pipeline: {
      submit: (request) => {
        submitted.push(request);
      },
      finalizeRequest,
      barkTarget,
      browserTarget,
      systemTarget,
      webhookTarget,
    },
    kinds: {
      listKinds: () => [...KINDS],
      confirmKind: async () => ({
        ok: true,
        view: { user: {}, revision: 9, writable: true, effective: {} },
      }),
    },
    channels: {
      probeCapabilities: () => Promise.resolve(CAPABILITIES),
      hostPlatform: () => "linux",
      undeterminedCapabilities: () => CAPABILITIES,
      dryRunTarget,
    },
  };
  installApi(deps);
  return { hub, frames, logger, submitted };
}

/** 取一条已注册的路由；没注册就直接抛，免得后面的断言在 undefined 上假绿。 */
function routeOf(routes: WebRoute[], path: string): WebRoute {
  const route = routes.find((item) => item.path === path);
  if (route === undefined) throw new Error(`路由未注册: ${path}`);
  return route;
}

/**
 * 走一次真实路由并等响应落地。壳对异步端点的 promise 只做 `catch` 收口、不往上传（见 route 块），
 * 故 `handler()` 立刻返回 undefined——等响应只能靠轮询 `headersSent`。
 */
async function request(routes: WebRoute[], path: string, req: IncomingMessage) {
  const captured = makeRes();
  routeOf(routes, path).handler(req, captured.res);
  await pollUntil(() => captured.rec.headersSent, `${path} 未写出响应`);
  return captured;
}

describe("路径表：对客户端的完整承诺", () => {
  it("恰好 8 条路径，且全部按 exact 注册（多一条就是多开一个浏览器入口）", () => {
    const { hub } = assemble();
    expect([...hub.routes.map((route) => route.path)].sort()).toEqual([...PATHS].sort());
    expect([...new Set(hub.routes.map((route) => route.kind))]).toEqual(["exact"]);
  });

  it.each(METHOD_TABLE)("%s 的方法表由 405 的 allow 头逐条列出", async (path, methods) => {
    const { hub } = assemble();
    const { rec, json } = await request(hub.routes, path, makeReq({ method: "PATCH", url: path }));
    expect(rec.status).toBe(405);
    expect(rec.headers.allow).toBe(methods.join(", "));
    expect(json()).toEqual({
      error: "method not allowed: PATCH",
      code: "METHOD_NOT_ALLOWED",
      status: 405,
    });
  });
});

describe("接线：端点与能力面一一对应", () => {
  it("四个端点各拿到自己那份能力面（接错线在编译期是合法的，只有装配面看得见）", async () => {
    const { hub, submitted } = assemble();

    const config = await request(
      hub.routes,
      "/api/dsh-notifier/config",
      makeReq({ url: "/api/dsh-notifier/config" }),
    );
    expect(config.json().revision).toBe(7);

    const history = await request(
      hub.routes,
      "/api/dsh-notifier/history",
      makeReq({ url: "/api/dsh-notifier/history" }),
    );
    expect(history.json().records).toEqual(HISTORY);

    const kinds = await request(
      hub.routes,
      "/api/dsh-notifier/kinds",
      makeReq({ url: "/api/dsh-notifier/kinds" }),
    );
    expect(kinds.json().kinds).toEqual(KINDS);

    const test = await request(
      hub.routes,
      "/api/dsh-notifier/test",
      makeReq({ method: "POST", url: "/api/dsh-notifier/test" }),
    );
    expect(test.rec.status).toBe(200);
    expect(submitted.map((entry) => entry.kind)).toEqual(["test"]);

    // 两个自检端点都要拿到 channels 域那一份：接错线（少传 `channels`）在编译期是合法的。
    const health = await request(
      hub.routes,
      "/api/dsh-notifier/health",
      makeReq({ url: "/api/dsh-notifier/health" }),
    );
    const healthHost = wire<{ capabilities: { host: { verdict: string } } }>(health.json());
    expect(healthHost.capabilities.host.verdict).toBe("degraded");

    const diagnostics = await request(
      hub.routes,
      "/api/dsh-notifier/diagnostics",
      makeReq({ url: "/api/dsh-notifier/diagnostics" }),
    );
    const diagnosticsHost = wire<{ capabilities: { host: HostCapabilities } }>(diagnostics.json());
    // 摘要与完整面必须同源：`/diagnostics` 给的就是装配接上的那一份（含 checked 与 remediation）。
    expect(diagnosticsHost.capabilities.host).toEqual(CAPABILITIES);
  });

  it("装配同时接上帧入口：帧经 /events 回放给新连接（接线断了页面永远收不到通知）", async () => {
    const { hub, frames } = assemble();
    expect(frames.handlers).toHaveLength(1);
    frames.handlers[0]!({
      kind: "done",
      frame: {
        pop: true,
        sound: { mode: "system" },
        whenVisible: false,
        title: "标题",
        body: "正文",
      },
    });

    const { rec } = await request(
      hub.routes,
      "/api/dsh-notifier/events",
      makeReq({ url: "/api/dsh-notifier/events" }),
    );
    expect(rec.headers["content-type"]).toBe("text/event-stream; charset=utf-8");
    expect(rec.text).toContain("标题");
  });
});

describe("生命周期", () => {
  it("release 摘掉全部路由与帧订阅（卸载后路由还在，等于插件卸载没生效）", () => {
    const { hub, frames } = assemble();
    expect(hub.disposed).toEqual([]);

    releaseApi();

    expect([...hub.disposed].sort()).toEqual([...PATHS].sort());
    expect(frames.disposedCount()).toBe(1);
  });

  it("重复装配当场抛错，release 之后可以再装配（卸载链可能走到不止一次）", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
    releaseApi();
    releaseApi();
    // 只断「没抛」不够：装上了与**静默空转**都不抛（实测把 install 改成见标记即 return，这条照样绿）。
    // 再装配的实质是「8 条路由又被挂回去」，就判这个。
    const again = assemble();
    expect(again.hub.routes.map((route) => route.path).sort()).toEqual([...PATHS].sort());
  });
});

packages/dsh-notifier/test/integration/s.source:
/**
 * dsh-notifier — #912 症状2端到端：dispatch 到 stores 到 GET /status 到 statusText，
 * 以及 POST /test fire-and-forget 时序。
 *
 * 真裁决管线 + 真 stores（隔离 DSH_HOME 落盘）+ 真 journal 端点 + 真客户端 statusText。
 * 投递出口是假件（秒回 failed/skipped，不起子进程、不联网）；落盘进隔离临时目录。
 * 不改 skipped 值域（ok/failed 锁死）：skipped 那条走历史直达到 statusText。
 */
import { rmSync } from "node:fs";
import { afterAll, afterEach, beforeEach, describe, expect, it } from "vitest";

import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../src/server/config/impl/model/type.ts";
import {
  HISTORY_FILE_NAME,
  STATUS_FILE_NAME,
  notifierFile,
} from "../../src/server/shared/interface.ts";
import type { NotifyMessage } from "../../src/server/pipeline/deps.ts";
import type { PipelineDeps } from "../../src/server/pipeline/deps.ts";
import type { DeliveryTarget } from "../../src/server/channels/interface.ts";
import type { DeliverResult } from "../../src/server/channels/impl/deliver/type.ts";
import { JournalEndpoints } from "../../src/server/api/impl/journal/index.ts";
import { ProbeEndpoints } from "../../src/server/api/impl/probe/index.ts";
import type { ChannelPort } from "../../src/server/api/deps.ts";
import { zh } from "../../src/client/locales.ts";
import { statusText } from "../../src/client/settings/parts/status.tsx";
import type { ChannelStatusMap } from "../../src/client/settings/parts/status.tsx";
import { jsonReq, makeLogger, makeRes, tempDshHome } from "../helpers.ts";
import { translateWithZh } from "../client-helpers.ts";

// 导入顺序纪律（同 stores/status.test.ts）：单例落盘路径在构造时定下，静态 import 会在
// 任何语句之前求值——顺序反了，落盘就写进真实 DSH home。impl 单例走 await import，且必须
// 在 tempDshHome() 之后。
const home = tempDshHome();
const historyFile = notifierFile(HISTORY_FILE_NAME);
const statusFile = notifierFile(STATUS_FILE_NAME);
const storeApi = await import("../../src/server/stores/interface.ts");
const pipelineApi = await import("../../src/server/pipeline/interface.ts");
// probe 构造要的 dry-run 出站与 config 纯函数（动态导入与上同纪）。
const { dryRunTarget } = await import("../../src/server/channels/interface.ts");
const { finalizeRequest, barkTarget, browserTarget, systemTarget, webhookTarget } =
  await import("../../src/server/pipeline/interface.ts");
const { resolveDraftChannels, normalizeConfig } =
  await import("../../src/server/config/interface.ts");

const installStores = storeApi.installStores;
const releaseStores = storeApi.releaseStores;
const appendHistory = storeApi.appendHistory;
const recordStatus = storeApi.recordStatus;
const readHistory = storeApi.readHistory;
const readStatus = storeApi.readStatus;
const clearHistory = storeApi.clearHistory;
const installPipeline = pipelineApi.installPipeline;
const releasePipeline = pipelineApi.releasePipeline;
const submit = pipelineApi.submit;

/** 装配真管线 + 真 stores，投递出口由调用方注入（假件，不联网）。 */
function assemble(
  deliver: (message: NotifyMessage, targets: DeliveryTarget[]) => Promise<DeliverResult[]>,
) {
  const logger = makeLogger();
  const config: NotifyConfig = { ...DEFAULT_CONFIG };
  installStores({ logger, config: { readConfig: () => ({ ...config }) } });
  const deps: PipelineDeps = {
    enabled: true,
    frames: { emit: () => {} },
    logger,
    config: { readConfig: () => ({ ...config }) },
    stores: { appendHistory, recordStatus },
    channels: { deliver },
  };
  installPipeline(deps);
  return new JournalEndpoints({ readHistory, clearHistory, readStatus });
}

beforeEach(() => {
  rmSync(historyFile, { force: true });
  rmSync(statusFile, { recursive: true, force: true });
});

afterEach(() => {
  releasePipeline();
  releaseStores();
});

afterAll(() => {
  home.dispose();
});

/** 等到历史出现 test 记录（落盘队列是异步的，等可见而不是等固定时长）。 */
async function pollTestHistory() {
  const deadline = Date.now() + 10_000;
  for (;;) {
    const records = await readHistory();
    const found = records.filter((record) => record.kind === "test");
    if (found.length > 0) return found;
    if (Date.now() > deadline) throw new Error("测试通知在 10s 内未落史");
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

/** 等到某频道的状态条目出现（内存镜像即时，等的是异步投递走完）。 */
async function pollStatusEntry(channelId: string) {
  const deadline = Date.now() + 10_000;
  for (;;) {
    const map = await readStatus();
    if (map[channelId] !== undefined) return map;
    if (Date.now() > deadline) throw new Error("频道状态在 10s 内未出现");
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

describe("dispatch 到 stores 到 GET /status 到 statusText（真 failed 翻页）", () => {
  it("失败投递经状态端点读回 failed，statusText 显示最近投递失败", async () => {
    const journal = assemble((_message, targets) =>
      Promise.resolve(
        targets.map(() => ({
          status: "failed",
          stage: "delivered",
          reason: { code: "reasonSystemPopupFailed", params: { bin: "notify-send" } },
          retryable: false,
        })),
      ),
    );
    submit({ kind: "test", title: "标题", body: "正文" });

    const historyFound = await pollTestHistory();
    // 三面一致其一：同一条 test 记录里 system 即失败（含投递原因码）
    const historyChannels = historyFound[0].channels ?? [];
    const failedItem = historyChannels.find((item) => item.channelId === "system");
    expect(failedItem?.status).toBe("failed");
    expect(failedItem?.reason?.code).toBe("reasonSystemPopupFailed");
    const map = await pollStatusEntry("system");
    const systemEntry = map.system;
    expect(systemEntry && systemEntry.lastStatus).toBe("failed");
    expect(systemEntry && typeof systemEntry.lastTs).toBe("number");

    const made = makeRes();
    await journal.readStatus(jsonReq({ method: "GET", url: "/api/dsh-notifier/status" }), made.res);
    expect(made.rec.status).toBe(200);
    const channels = made.json().channels as Record<string, { lastStatus: string; lastTs: number }>;
    const got = channels.system;
    expect(got && got.lastStatus).toBe("failed");
    expect(got && typeof got.lastTs).toBe("number");

    const text = statusText("system", channels as ChannelStatusMap, translateWithZh);
    expect(text).toContain(zh.chLastFail);
  });

  it("skipped 不写状态但落历史：状态端点无条目，statusText 经历史直达给解释", async () => {
    const journal = assemble((_message, targets) =>
      Promise.resolve(
        targets.map(() => ({ status: "skipped", reason: { code: "reasonSkipConfig" } })),
      ),
    );
    submit({ kind: "test", title: "标题", body: "正文" });

    const found = await pollTestHistory();
    const first = found[0];
    expect(first && first.channels).toContainEqual({
      channelId: "system",
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });

    const made = makeRes();
    await journal.readStatus(jsonReq({ method: "GET", url: "/api/dsh-notifier/status" }), made.res);
    expect(made.rec.status).toBe(200);
    // skipped 没有“最后一次投递结论”：状态表里没有该频道的键（值域 ok/failed 锁死）。
    expect(made.json().channels).toEqual({});

    const records = await readHistory();
    const text = statusText("system", {}, translateWithZh, records);
    expect(text).toContain(zh.chNeverSent);
    expect(text).toContain(zh.reasonSkipConfig);
    expect(text).toContain(zh.chSkippedSeeHistory);
  });
});

describe("POST /test 时序：先 200 受理，投递终态随后才可见", () => {
  it("响应返回时历史为空；放行投递后历史与状态相继出现", async () => {
    let releaseGate: (() => void) | undefined;
    const gate = new Promise<void>((resolve) => {
      releaseGate = resolve;
    });
    const logger = makeLogger();
    const config: NotifyConfig = { ...DEFAULT_CONFIG };
    installStores({ logger, config: { readConfig: () => ({ ...config }) } });
    installPipeline({
      enabled: true,
      frames: { emit: () => {} },
      logger,
      config: { readConfig: () => ({ ...config }) },
      stores: { appendHistory, recordStatus },
      channels: {
        deliver: (_message, targets) =>
          gate.then((): DeliverResult[] =>
            targets.map(() => ({ status: "ok", stage: "delivered" })),
          ),
      },
    });
    const channels: ChannelPort = {
      probeCapabilities: () => Promise.reject(new Error("本用例不探测")),
      hostPlatform: () => "linux",
      undeterminedCapabilities: () => {
        throw new Error("本用例不探测");
      },
      dryRunTarget,
    };
    const probe = new ProbeEndpoints(
      {
        submit,
        finalizeRequest,
        barkTarget,
        browserTarget,
        systemTarget,
        webhookTarget,
      },
      channels,
      makeLogger(),
      {
        readConfig: () => ({ ...config }),
        readSettingsView: () => {
          throw new Error("本用例不读视图");
        },
        writeConfig: () => Promise.reject(new Error("本用例不写配置")),
        resolveDraftChannels,
        normalizeConfig,
      },
    );

    const made = makeRes();
    await probe.test(
      jsonReq({ method: "POST", url: "/api/dsh-notifier/test", body: {} }),
      made.res,
    );
    expect(made.rec.status).toBe(200);
    expect(made.json()).toEqual({ ok: true, sseConnections: 0 });
    // fire-and-forget：响应只承诺已受理，投递还在门后——此刻历史必须仍是空的。
    expect(await readHistory()).toEqual([]);

    if (releaseGate !== undefined) releaseGate();
    const released = await pollTestHistory();
    const releasedChannels = released[0].channels ?? [];
    const okItem = releasedChannels.find((item) => item.channelId === "browser");
    expect(okItem?.status).toBe("ok");
    const map = await pollStatusEntry("browser");
    const browserEntry = map.browser;
    expect(browserEntry && browserEntry.lastStatus).toBe("ok");
  });
});

